export function submissionSummaryHTML({mode='passed',fragmented=false,score=84}={}){
  const answered=mode==='partial'?4:5,notice=mode==='failed'?'<p>你没有达到闯关条件，请修改后再提交。</p>':mode==='pending'?'<p>主观题待批改</p>':'';
  const summary=`<h2>答题小结</h2><p>完成本板块内全部必修练习且客观题正确率≥60</p>${notice}<div class="score"><span>${score}</span><span>分</span></div>`+(fragmented?`<p>共<b>5</b>道题，主观题<strong>5</strong>道</p><p>主观题 <span><i aria-hidden="true">○</i>已作答 (<b>${answered}</b>/<b>5</b>)</span> <span><i aria-hidden="true">○</i>未作答 (<b>${5-answered}</b>/<b>5</b>)</span></p>`:`<p>共5道题，主观题5道</p><p>主观题 <span>已作答 (${answered}/5)</span> <span>未作答 (${5-answered}/5)</span></p>`);
  return `<!doctype html><html><body><header><nav class="pc-break-crumb"><span class="pc-break-crumb-text">English Book</span><span class="pc-break-crumb-text">Time off</span><span class="pc-break-crumb-text">Building your language</span></nav><div class="pc-header-tab-activity">Building your language</div><div class="pc-task pc-header-task-activity">Exercise 3</div></header><main class="pc-main-container" id="exercise">${Array.from({length:5},(_,i)=>`<fieldset><legend>Translate sentence ${i+1}.</legend><textarea></textarea></fieldset>`).join('')}</main><footer class="question-common-course-page" id="footer"><button>提交</button></footer><script>
  window.submits=0;window.continues=0;window.directoryPolls=0;window.directoryAcknowledged=false;window.submittedValues=[];
  const exercise=document.getElementById('exercise'),footer=document.getElementById('footer');
  footer.firstElementChild.onclick=()=>{window.submits++;window.submittedValues=[...document.querySelectorAll('textarea')].map(el=>el.value);exercise.innerHTML=${JSON.stringify(summary)};footer.innerHTML='<button>继续学习</button>';footer.firstElementChild.onclick=()=>{window.continues++;window.directoryAcknowledged=true;document.querySelector('.pc-header-task-activity').textContent='Unrequested exercise';exercise.innerHTML='<p>Another exercise that must not be filled through this button.</p><textarea id="unrequested"></textarea>';footer.innerHTML='';history.replaceState(null,'','#unrequested');};};
  </script></body></html>`;
}
